```
import React, { useState,useEffect } from 'react';

const Autosuggest = ({ data, onChange }) => {
  const [value, setValue] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [activeSuggestionIndex, setActiveSuggestionIndex] = useState(-1);

  useEffect(() => {
    const suggestions = data.filter((item) => {
      const suggestionValue = item.toString().toLowerCase();
      const inputValue = value.toLowerCase();
      return suggestionValue.startsWith(inputValue);
    });
    setSuggestions(suggestions);
  }, [data, value]);

  const handleInputChange = (e) => {
    setValue(e.target.value);
  };

  const handleKeydown = (e) => {
    if (e.key === 'Enter') {
      onChange(suggestions[activeSuggestionIndex]);
    } else if (e.key === 'ArrowDown') {
      setActiveSuggestionIndex((prevIndex) => prevIndex + 1);
    } else if (e.key === 'ArrowUp') {
      setActiveSuggestionIndex((prevIndex) => Math.max(0, prevIndex - 1));
    }
  };

  return (
    <div>
      <input
        type="text"
        value={value}
        onChange={handleInputChange}
        onKeyDown={handleKeydown}
        placeholder="Type to search..."
      />
      <ul>
        {suggestions.map((suggestion, index) => (
          <li
            key={index}
            className={activeSuggestionIndex === index ? 'active' : ''}
            onClick={() => onChange(suggestion)}
          >
            {suggestion}
          </li>
        ))}
      </ul>
    </div>
  );
};

export default Autosuggest;
```
