using System;
using System.Net;
using System.Net.Http;
using System.Threading;

class Program
{
    static void Main(string[] args)
    {
        // Créer un nouvel objet HttpListener
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/"); // définir la racine du serveur
        listener.Start(); // démarrer le serveur

        Console.WriteLine("Server started. Listening on port 8080...");

        // Boucle éternelle pour écouter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Vérifier si la requête est pour la page /hello
            if (request.Url.AbsolutePath == "/hello")
            {
                // Envoyer une réponse HTTP 200 avec le contenu "Hello"
                context.Response.StatusCode = 200;
                context.Response.ContentType = "text/plain";
                using (var streamWriter = new StreamWriter(context.Response.OutputStream))
                {
                    streamWriter.WriteLine("Hello");
                }
            }
            else
            {
                // Envoyer une réponse HTTP 404 si la page n'est pas trovée
                context.Response.StatusCode = 404;
                context.Response.ContentType = "text/plain";
                using (var streamWriter = new StreamWriter(context.Response.OutputStream))
                {
                    streamWriter.WriteLine("Page not found");
                }
            }

            // Fermer la connexion
            context.Response.Close();
        }
    }
}
